			row[WhsDocketLineSchema.Constants.WE_WL                             ] = DBNull.Value;
			row[WhsDocketLineSchema.Constants.WE_WL_TransferFrom                ] = DBNull.Value;
			row[WhsDocketLineSchema.Constants.WE_WPL_PutawayLine                ] = DBNull.Value;
		}

